import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'pathslash';
import { parseSync } from 'vite';
import { TYPED_CONFIG_FILE } from './config-loader.ts';
import { validateConfig, type VoidConfig } from './config.ts';

export const GENERATED_MARKERS: ReadonlyArray<string> = [
  '// Generated by void migrate.',
  '// Generated from void.json by void migrate.',
  '// Generated by void init.',
];

export function renderVoidConfig(
  config: VoidConfig,
  marker: string = GENERATED_MARKERS[0],
): string {
  return `${marker}\nimport { defineConfig } from 'void/config';\n\nexport default defineConfig(${JSON.stringify(config, null, 2)});\n`;
}

type StaticNode = {
  type: string;
  body?: Array<StaticNode>;
  declaration?: StaticNode;
  callee?: StaticNode;
  arguments?: Array<StaticNode>;
  elements?: Array<StaticNode | null>;
  properties?: Array<StaticNode>;
  key?: StaticNode;
  value?: unknown;
  name?: string;
  operator?: string;
  argument?: StaticNode;
  source?: { value: unknown };
  specifiers?: Array<{ imported?: { name?: string }; local?: { name?: string } }>;
  computed?: boolean;
  method?: boolean;
  kind?: string;
};

function isStaticValue(node: StaticNode | null | undefined): boolean {
  if (!node) {
    return false;
  }
  if (node.type === 'Literal') {
    return node.value === null || ['string', 'number', 'boolean'].includes(typeof node.value);
  }
  if (node.type === 'UnaryExpression') {
    return (
      node.operator === '-' &&
      node.argument?.type === 'Literal' &&
      typeof node.argument.value === 'number'
    );
  }
  if (node.type === 'ArrayExpression') {
    return node.elements?.every(isStaticValue) ?? false;
  }
  if (node.type !== 'ObjectExpression') {
    return false;
  }
  return (
    node.properties?.every(
      (property) =>
        property.type === 'Property' &&
        property.kind === 'init' &&
        !property.computed &&
        !property.method &&
        (property.key?.type === 'Identifier' || property.key?.type === 'Literal') &&
        isStaticValue(property.value as StaticNode),
    ) ?? false
  );
}

function isGeneratedStaticConfig(source: string): boolean {
  if (!GENERATED_MARKERS.some((marker) => source.startsWith(marker))) {
    return false;
  }
  let program: StaticNode;
  try {
    const parsed = parseSync(TYPED_CONFIG_FILE, source, {
      // Generated config is plain JavaScript; authored TypeScript must stay untouched.
      lang: 'js',
      sourceType: 'module',
      preserveParens: false,
      showSemanticErrors: true,
    });
    if (
      parsed.errors.length > 0 ||
      parsed.comments.length !== 1 ||
      !GENERATED_MARKERS.includes(`// ${parsed.comments[0]?.value.trim()}`)
    ) {
      return false;
    }
    program = parsed.program as unknown as StaticNode;
  } catch {
    return false;
  }
  const [importDeclaration, exportDeclaration] = program.body ?? [];
  const call = exportDeclaration?.declaration;
  return (
    program.body?.length === 2 &&
    importDeclaration?.type === 'ImportDeclaration' &&
    importDeclaration.source?.value === 'void/config' &&
    importDeclaration.specifiers?.length === 1 &&
    importDeclaration.specifiers[0]?.imported?.name === 'defineConfig' &&
    importDeclaration.specifiers[0]?.local?.name === 'defineConfig' &&
    exportDeclaration?.type === 'ExportDefaultDeclaration' &&
    call?.type === 'CallExpression' &&
    call.callee?.name === 'defineConfig' &&
    call.arguments?.length === 1 &&
    isStaticValue(call.arguments[0])
  );
}

export function canRewriteVoidProjectConfig(root: string): boolean {
  const path = join(root, TYPED_CONFIG_FILE);
  return !existsSync(path) || isGeneratedStaticConfig(readFileSync(path, 'utf8'));
}

/** Update CLI-owned static config without silently rewriting authored TypeScript. */
export function writeVoidProjectConfig(root: string, config: VoidConfig): void {
  validateConfig(config, TYPED_CONFIG_FILE);
  const path = join(root, TYPED_CONFIG_FILE);
  if (existsSync(path)) {
    const original = readFileSync(path, 'utf8');
    if (!isGeneratedStaticConfig(original)) {
      throw new Error(
        `config: ${TYPED_CONFIG_FILE} contains authored TypeScript or comments. Update it directly and rerun the command.`,
      );
    }
  }
  writeFileSync(path, renderVoidConfig(config, '// Generated by void init.'));
}
